```python
# Python 3程序，用于验证IPv4地址
import re

def validate_char(s):
    """检查IP地址是否包含有效字符的函数"""
    pattern = re.compile(r'[@_!#$%^&*()<>?/\|}{~:]')
    if(pattern.search(s) == None):
        return True
    else:
        return False

def validate_octet(s):
    """检查通配符的函数"""
    if s == "*":
        return True
    if s == "-":
        return True
    if not s.isdigit() or int(s) > 255:
        return False
    return True

def validate_IPv4(s):
    """验证给定IPv4地址的函数"""
    l = s.split(".")
    if not validate_char(s):
        return False
    if len(l) != 4:
        return False
    for x in l:
        if not validate_octet(x):
            return False
    return True

# 驱动程序
