这是一个利用贪心算法进行字符串匹配的Python程序示例：

```
def string_match_greedy(A, B):
    for i in range(len(A)-len(B)+1):
        j = 0
        while j<len(B) and B[j] == A[i+j]:
            j+=1
        if j == len(B):
            return i
    return -1

A = "ababcab"
B = "cab"
index = string_match_greedy(A, B)
if index != -1:
    print(f"在字符串A中找到了字符串B，索引为{index}")
else:
    print("在字符串A中未找到字符串B")
```

解释：`string_match_greedy`函数接受两个输入字符串`A`和`B`。外部的`for`循环迭代`A`字符串长度减去`B`字符串长度加一的范围。内部的`while`循环检查`B`的第`j`个字符是否等于`A`的第`i+j`个字符，如果是，则将`j`加1。如果`j`达到了`B`的长度，则意味着在`A`中找到了`B`，函数返回索引`i`。如果在`A`中未找到`B`，函数返回`-1`。

这是一个C++中简单的链表实现代码：

```cpp
#include<iostream>
using namespace std;

class Node {
public:
    int data;
    Node* next;
    Node(int d) {
        data = d;
        next = NULL;
    }
};

class LinkedList {
private:
    Node* head;
public:
    LinkedList() {
        head = NULL;
    }

    void add(int d) {
        if (head == NULL) {
            head = new Node(d);
            return;
        }
        Node* temp = head;
        while (temp->next != NULL) {
            temp = temp->next;
        }
        temp->next = new Node(d);
        return;
    }

    void print() {
        Node* temp = head;
        while (temp != NULL) {
            cout << temp->data << " ";
            temp = temp->next;
        }
        cout << "\n";
    }

    void remove(int d) {
        if (head == NULL) return;
        Node* temp = head;
        if (head->data == d) {
            head = head->next;
            delete temp;
            return;
        }
        while (temp->next != NULL && temp->next->data != d) {
            temp = temp->next;
        }
        if (temp->next == NULL) return;
        Node* to_remove = temp->next;
        temp->next = temp->next->next;
        delete to_remove;
        return;
    }
};
```

