这是一个Python脚本，可以将数字转换为英文单词，最大支持999,999,999。代码如下：

```python
def convert_number_to_words(num):
    below_20 = ["", "One ", "Two ", "Three ", "Four ", "Five ", "Six ", "Seven ", "Eight ", "Nine ", "Ten ", "Eleven ", "Twelve ", "Thirteen ", "Fourteen ", "Fifteen ", "Sixteen ", "Seventeen ", "Eighteen ", "Nineteen "]
    tens = ["", "", "Twenty ", "Thirty ", "Forty ", "Fifty ", "Sixty ", "Seventy ", "Eighty ", "Ninety "]
    above_100 = ["Hundred ", "Thousand ", "Million ", "Billion "]

    if num == 0:
        return "Zero"
    if num < 0:
        return "Minus " + convert_number_to_words(-num)

    result = ""
    if num < 20:
        result = below_20[num]
    elif num < 100:
        result = tens[num // 10] + convert_number_to_words(num % 10)
    elif num < 1000:
        result = below_20[num // 100] + above_100[0] + convert_number_to_words(num % 100)
    elif num < 1000000:
        result = convert_number_to_words(num // 1000) + above_100[1] + convert_number_to_words(num % 1000)
    elif num < 1000000000:
        result = convert_number_to_words(num // 1000000) + above_100[2] + convert_number_to_words(num % 1000000)

    return result.strip()

print(convert_number_to_words(123456789))
print(convert_number_to_words(111))
print(convert_number_to_words(0))
print(convert_number_to_words(1))
print(convert_number_to_words(-12345))
print(convert_number_to_words(100))
print(convert_number_to_words(100000))
```

