以下是一个C++程序，用于反转数组中的元素：

```c++
#include <iostream>
using namespace std;

void reverseArray(int arr[], int n) {
    // 初始化开始和结束索引
    int start = 0;
    int end = n-1;
    // 循环遍历数组的一半
    while (start < end) {
        // 交换开始和结束位置的值
        int temp = arr[start];
        arr[start] = arr[end];
        arr[end] = temp;
        // 增加开始索引，减少结束索引
        start++;
        end--;
    }
}

void printArray(int arr[], int n) {
    // 循环遍历数组并打印出值
    for (int i = 0; i < n; i++)
        cout << arr[i] << " ";
    cout << endl;
}

int main() {
    int arr[] = {1, 2, 3, 4, 5, 6};
    int n = sizeof(arr)/sizeof(arr[0]);

    cout << "原始数组：";
    printArray(arr, n);

    // 反转数组
    reverseArray(arr, n);

    cout << "反转后的数组：";
    printArray(arr, n);

    return 0;
}
```

