from flask import Flask, jsonify

app = Flask(__name__)

def is_prime(num):
    if num <= 1:
        return False
    for i in range(2, num):
        if num % i == 0:
            return False
    return True

def get_next_prime(num):
    next_prime = num + 1
    while not is_prime(next_prime):
        next_prime += 1
    return next_prime

@app.route('/nextprime/<int:num>', methods=['GET'])
def next_prime(num):
    try:
        next_prime = get_next_prime(num)
        return jsonify({'next_prime': next_prime})
    except ValueError:
        return jsonify({'error': '无效输入，请输入一个整数'})

if __name__ == '__main__':
    app.run()
```

