                board[x][y] = ai_player
                if has_winner(board) == ai_player:
                    return
                board[x][y] = " "
    # 检查玩家是否可以获胜并进行阻止
    player = "X" if ai_player == "O" else "O"
    for x in range(3):
        for y in range(3):
            if board[x][y] == " ":
                board[x][y] = player
                if has_winner(board) == player:
                    board[x][y] = ai_player
                    return
                board[x][y] = " "
    # 进行随机移动
    available_moves = [(x, y) for x in range(3) for y in range(3) if board[x][y] == " "]
    x, y = random.choice(available_moves)
    board[x][y] = ai_player
```

