```java 
public class MyDataStructure {
    private int maxSize; // 数据结构的最大大小
    private int[] data; // 存储数据的数组
    private int top; // 数据结构的顶部

    public DataStructure(int size) {
        maxSize = size;
        data = new int[maxSize];
        top = 0;
    }

    // 向数据结构中添加元素的方法
    public void push(int value) {
        if (!isFull()) {
            data[top++] = value;
        } else {
            // 数据结构已满的错误处理
            System.out.println("数据结构已满。");
        }
    }

    // 从数据结构中删除元素的方法
    public int pop() {
        if (!isEmpty()) {
            return data[--top];
        } else {
            // 数据结构为空的错误处理
            System.out.println("数据结构为空。");
            return -1;
        }
    }

    // 检查数据结构是否为空的方法
    public boolean isEmpty() {
        return top == 0;
    }

    // 检查数据结构是否已满的方法
    public boolean isFull() {
        return top == maxSize;
    }

    // 返回数据结构的大小的方法
    public int size() {
        return top;
    }
}
```

